"""Localized action errors with readable English fallbacks for logs."""
from homeassistant.exceptions import HomeAssistantError
from .const import DOMAIN

MESSAGES = {'unknown_control': 'Unknown control field.', 'missing_e2': 'No E2 settings template. Change a setting once on the HMI to capture it. B3 cannot replace it.', 'e2_not_sent': 'E2 command was not sent: {detail}', 'fast_requires_dhw': 'Enable DHW and wait for confirmation before enabling Fast hot water.', 'disconnected': 'No TCP connection or current pump telemetry.', 'resync': 'Waiting for a complete new telemetry snapshot after an unconfirmed command. The E2 template is retained.', 'missing_telemetry': 'Missing control readings: {fields}', 'stale_telemetry': 'Outdated control readings: {fields}', 'not_ready': 'Control is not ready.', 'readiness_lost': 'Control readiness was lost before 55. The command was not sent.', 'fast_dhw_changed': 'DHW was disabled before 55. Fast hot water was not sent.', 'e2_transport_error': 'E2 was not sent or a transport error occurred: {detail}', 'no_confirmation': 'No command confirmation from the pump. Check the HMI; the command may have been executed.', 'b6_preflight': 'B6 parameter was not sent. Refresh or validation failed: {detail}', 'b6_not_ready': 'No connection or current configuration byte. Refresh settings and wait for the B3 reply.', 'parameter_not_sent': 'Parameter was not sent: {detail}', 'b6_no_reply': 'No matching 03 reply to B6. Check the HMI setting. The command was not retried.', 'b6_readback_failed': 'The pump acknowledged B6, but B3 readback timed out. Check the setting. The write was not retried.', 'b6_readback_mismatch': 'B3 readback returned a different value. Check the HMI setting.', 'b3_refresh_failed': 'Could not read B3 settings: {detail}. No settings were changed.', 'heating_mode': 'Heating supports only heat and off modes.', 'heating_range': 'Heating setpoint: {minimum}–{maximum}°C, in 1°C steps.', 'invalid_name_language': 'Choose System, Polish or English.', 'language_save_failed': 'Could not save the entity name language: {detail}'}


def localized_error(key, **placeholders):
    return HomeAssistantError(MESSAGES[key].format(**placeholders),
                              translation_domain=DOMAIN, translation_key=key,
                              translation_placeholders=placeholders)
